@startuml

class HomeTec {
  + Name : string
  + Location : string
}

class SensorController {
  + LogOn(username: string, password: string): void
  + QuerySensorValues(sensor: Sensor): void
  + SetThreshold(sensor: Sensor, threshold: float): void
  + ConfigureSensor(sensor: Sensor, room: Room, description: string): void
}

class Apartment {
  + Address : string
  + EmailAddress : string
}

class Inhabitant {
  + Username : string
  + Password : string
  + IsAdmin : boolean
}

class Room {
  + Description : string
}

class Sensor {
  + VendorId : string
  + Description : string
  + Unit : Unit
  + Threshold : float
  + GetLastValue(): float
}

enum Unit {
  CELSIUS
  WATT
}

class TemperatureSensor extends Sensor {
  + MinValue : float
  + MaxValue : float
}

class PowerSensor extends Sensor {
  + CounterReading : float
}

class MeasuredValue {
  + Timestamp : datetime
  + Value : float
}

class EMonitor {
  + CheckThresholds()
}

HomeTec "1" -- "0..*" SensorController
SensorController "1" -- "1" Apartment
Apartment "1" -- "1..*" Inhabitant
Apartment "1" -- "1..*" Room
Room "1" -- "1..*" Sensor
Sensor "1" -- "0..*" MeasuredValue

@enduml

